import Testing
@testable import TactileCore

// Byte-exact vectors for every report Tactile builds (0x31/0x02 are pinned in
// OutputReportTests). Generated by tools/gen_vectors.py, an independent Python
// implementation of PROTOCOL.md that uses zlib.crc32.
let hapSeq15 = hex("32 f0 91 07 fe 00 00 00 00 ff 0f 92 40 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 7f 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 1b 98 01 d1")
let hapSeq16Silent = hex("32 00 91 07 fe 00 00 00 00 ff 10 92 40 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 8f 18 22 fa")
let spkSeq0 = hex("36 00 05 f4 01 02 03 04 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 b9 78 06 b1")
let spkSeq1 = hex("36 10 03 f4 aa 55 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 90 ea e0 23")
let spkUSB = hex("36 00 02 f4 09 00 00 00 00 00 00 00 00 00 00 00")
let btAudio = hex("31 00 10 a0 00 00 00 00 c8 00 30 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 42 7e 68 72")
let btRumbleOffV2 = hex("31 00 10 02 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 04 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 e8 f9 dd 97")
let btEmptySeq1 = hex("31 10 10 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 1c f5 29 5f")

/// Bit-by-bit CRC-32 (no table), seeded with a one-byte HID prefix: a second,
/// independent check of the table implementation and of the seed byte.
private func bitwiseCRC(prefix: UInt8, _ bytes: ArraySlice<UInt8>) -> UInt32 {
    var c: UInt32 = 0xFFFF_FFFF
    for b in [prefix] + Array(bytes) {
        c ^= UInt32(b)
        for _ in 0..<8 { c = c & 1 != 0 ? (c >> 1) ^ 0xEDB8_8320 : c >> 1 }
    }
    return ~c
}

private func storedCRC(_ r: [UInt8]) -> UInt32 {
    let n = r.count - 4
    return UInt32(r[n]) | UInt32(r[n + 1]) << 8 | UInt32(r[n + 2]) << 16 | UInt32(r[n + 3]) << 24
}

@Suite struct ReportGoldenTests {
    @Test func crcSeedIsTheOutputTransactionHeader() {
        #expect(CRC32.Prefix.output.rawValue == 0xA2)
        #expect(CRC32.Prefix.input.rawValue == 0xA1)
        for r in [hapSeq15, hapSeq16Silent, spkSeq0, spkSeq1, btAudio, btRumbleOffV2, btEmptySeq1] {
            #expect(storedCRC(r) == bitwiseCRC(prefix: 0xA2, r[0..<(r.count - 4)]))
            #expect(storedCRC(r) != bitwiseCRC(prefix: 0xA1, r[0..<(r.count - 4)]))
        }
    }

    @Test func hapticsReportSizeSequenceCounterAndWrap() {
        var b = HapticsReportBuilder()
        for _ in 0..<15 { _ = b.build(samples: []) }
        let r15 = b.build(samples: [Int8](repeating: 127, count: 64))
        #expect(r15.count == 141)
        #expect(r15 == hapSeq15)
        let r16 = b.build(samples: [])
        #expect(r16 == hapSeq16Silent)   // sequence wraps 15 -> 0, counter keeps counting
        #expect(b.sequence == 1 && b.counter == 17)
        for _ in 0..<(256 - 17) { _ = b.build(samples: []) }
        #expect(b.counter == 0)          // 8-bit counter wraps
    }

    @Test func speakerReportLayoutSequenceAndCRC() throws {
        var b = SpeakerAudioReportBuilder(framing: SpeakerAudioFraming(reportLength: 72))
        let r0 = try b.build(opusPacket: [0xF4, 1, 2, 3, 4])
        #expect(r0.count == 72)
        #expect(r0 == spkSeq0)
        #expect(try b.build(opusPacket: [0xF4, 0xAA, 0x55]) == spkSeq1)
        for _ in 0..<14 { _ = try b.build(opusPacket: [0xF4]) }
        #expect(b.sequence == 0)         // 4-bit sequence wraps after 16 reports
        // 72 - id - seq - length - CRC
        #expect(b.framing.maxPacketBytes == 72 - 3 - 4)
    }

    @Test func usbSpeakerReportHasNoCRC() throws {
        var f = SpeakerAudioFraming(reportLength: 16)
        f.crc = false
        var b = SpeakerAudioReportBuilder(framing: f)
        #expect(try b.build(opusPacket: [0xF4, 9]) == spkUSB)
    }

    @Test func audioRoutingReport() {
        var b = OutputReportBuilder(features: FeatureSet(vibrationV2: true, hasEdgeButtons: false))
        let r = b.build(OutputState(audio: AudioSettings(speakerVolume: 200, outputPath: .speaker)), transport: .bluetooth)
        #expect(r.count == 78)
        #expect(r == btAudio)
    }

    /// SDL documents valid_flag0 bit 1 as "disable audio haptics": the
    /// rumble-off report sets it, the following empty report clears it.
    @Test func hapticsHandBackPair() {
        var b = OutputReportBuilder(features: FeatureSet(vibrationV2: true, hasEdgeButtons: false))
        let off = b.build(OutputState(rumble: .off), transport: .bluetooth)
        let empty = b.build(OutputState(), transport: .bluetooth)
        #expect(off == btRumbleOffV2)
        #expect(empty == btEmptySeq1)
        #expect(off[3] & OutputLayout.flag0HapticsSelect != 0)
        #expect(empty[3] & OutputLayout.flag0HapticsSelect == 0)
    }
}
